var exist = function(board, word) {
    if (word.length === 0) return true;
    if (!board || !board.length || !board[0].length) return false;
    const rows = board.length;
    const cols = board[0].length;

    const search = (row, col, index) => {
        if (index === word.length) return true;
        if (row < 0 || row >= rows || col < 0 || col >= cols || board[row][col] !== word[index]) {
            return false;
        }
        const saved = board[row][col];
        board[row][col] = '#';
        const found =
            search(row + 1, col, index + 1) ||
            search(row - 1, col, index + 1) ||
            search(row, col + 1, index + 1) ||
            search(row, col - 1, index + 1);
        board[row][col] = saved;
        return found;
    };

    for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
            if (search(row, col, 0)) return true;
        }
    }
    return false;
};

solution.python:
from typing import List


class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        if word == "":
            return True
        if not board or not board[0]:
            return False

        rows, cols = len(board), len(board[0])

        def search(row: int, col: int, index: int) -> bool:
            if index == len(word):
                return True
            if (
                row < 0
                or row >= rows
                or col < 0
                or col >= cols
                or board[row][col] != word[index]
            ):
                return False

            saved = board[row][col]
            board[row][col] = "#"
            found = (
                search(row + 1, col, index + 1)
                or search(row - 1, col, index + 1)
                or search(row, col + 1, index + 1)
                or search(row, col - 1, index + 1)
            )
            board[row][col] = saved
            return found

        for row in range(rows):
            for col in range(cols):
                if search(row, col, 0):
                    return True
        return False
